gTA(){return"\u041d\u0430 \u0442\u0430\u0437\u0438 \u043a\u043e\u043c\u043f\u0438\u043b\u0430\u0446\u0438\u044f \u043d\u0435 \u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u043e \u0434\u0430 \u043e\u0431\u0449\u0443\u0432\u0430 \u0441 \u0442\u043e\u0432\u0430 \u0432\u043d\u0435\u0434\u0440\u044f\u0432\u0430\u043d\u0435 \u043d\u0430 NeoAgent."},
gTB(){return"\u0422\u043e\u0437\u0438 \u0440\u0430\u0431\u043e\u0442\u0435\u043d \u043f\u043b\u043e\u0442 \u0435 \u0441\u0432\u044a\u0440\u0437\u0430\u043d"},
gmP(){return"\u0422\u043e\u0432\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e"},
TC(a){return"\u0422\u043e\u0432\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e: "+A.q(a)},
