O1(a){return"\u0421\u0430\u043c\u043e \u043a\u043e\u0433\u0430\u0442\u043e \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u043e \u043b\u0438\u0446\u0435 \u043c\u0430\u0440\u043a\u0438\u0440\u0430 "+a+", \u043e\u0441\u0432\u0435\u043d \u0430\u043a\u043e \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0433\u0440\u0443\u043f\u0430"},
O3(a){return"\u0421\u0430\u043c\u043e \u043a\u043e\u0433\u0430\u0442\u043e "+a+" \u0435 \u043c\u0430\u0440\u043a\u0438\u0440\u0430\u043d, \u043e\u0441\u0432\u0435\u043d \u0430\u043a\u043e \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0438\u0442\u0435 \u0433\u0440\u0443\u043f\u0430"},
y7(a,b){return""+a+" \u043e\u0442 "+b+" \u0433\u0440\u0443\u043f\u0438 \u0441\u0435 \u043f\u0440\u0438\u0441\u044a\u0435\u0434\u0438\u043d\u044f\u0432\u0430\u0442 \u043a\u044a\u043c \u043e\u0431\u0438\u043a\u043d\u043e\u0432\u0435\u043d \u0447\u0430\u0442 \u0441 \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0438 \u0445\u043e\u0440\u0430"},
TE(a){return"\u0422\u043e\u0432\u0430 \u043d\u0435 \u043e\u0434\u043e\u0431\u0440\u044f\u0432\u0430 \u043d\u043e\u0432\u0438 \u0445\u043e\u0440\u0430. \u0415\u0442\u0438\u043a\u0435\u0442\u0438 \u0438 \u043e\u0442\u0433\u043e\u0432\u043e\u0440\u0438 \u043e\u0442 \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0438 \u0445\u043e\u0440\u0430 \u0432\u0438\u043d\u0430\u0433\u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0432\u0430\u0442 \u043e\u0442\u0433\u043e\u0432\u043e\u0440. \u0412\u043a\u043b\u044e\u0447\u0435\u0442\u0435 \u0433\u0440\u0443\u043f\u0430, \u0430\u043a\u043e "+a+u.g2},
