gu9(){return"\u041c\u043e\u0434\u0435\u043b\u0438 \u0437\u0430 \u0432\u0437\u0435\u043c\u0430\u043d\u0435 \u043d\u0430 \u0440\u0435\u0448\u0435\u043d\u0438\u044f, \u043a\u043e\u0438\u0442\u043e \u043f\u0440\u0430\u0432\u044f\u0442 \u0440\u0430\u0437\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u0435 \u0437\u0430\u0434 \u043a\u0443\u043b\u0438\u0441\u0438\u0442\u0435 \u0437\u0430 \u0447\u0430\u0441\u0442\u0438 \u043e\u0442 \u0441\u0435\u043a\u0443\u043d\u0434\u0430\u0442\u0430: \u0440\u0435\u0434\u043e\u0432\u0435\u043d \u0433\u0440\u0443\u043f\u043e\u0432 \u0447\u0430\u0442 \u0438 \u0441\u0442\u044a\u043f\u043a\u0438 \u043d\u0430 \u0431\u0440\u0430\u0443\u0437\u044a\u0440\u0430. \u0412\u0430\u0448\u0438\u044f\u0442 \u043c\u043e\u0434\u0435\u043b \u043d\u0430 \u0447\u0430\u0442 \u0432\u0441\u0435 \u043e\u0449\u0435 \u043f\u0438\u0448\u0435 \u0432\u0441\u0435\u043a\u0438 \u043e\u0442\u0433\u043e\u0432\u043e\u0440."},
gu8(){return"\u041c\u043e\u0434\u0435\u043b\u044a\u0442 SystemOne \u0440\u0435\u0448\u0430\u0432\u0430 \u043a\u043e\u0433\u0430 \u0434\u0430 \u0433\u043e\u0432\u043e\u0440\u0438, \u0434\u043e\u043a\u0430\u0442\u043e \u0435 \u0432\u043a\u043b\u044e\u0447\u0435\u043d; \u0442\u043e\u0437\u0438 \u043c\u043e\u0434\u0435\u043b \u0435 \u0440\u0435\u0437\u0435\u0440\u0432\u0435\u043d."},
ys(a){return""+a+" \u043e\u0442\u0431\u0435\u043b\u044f\u0437\u0430 \u0433\u043e\u043b \u043e\u0442 SystemOne"},
guc(){return"SystemOne \u043e\u0442\u0431\u0435\u043b\u044f\u0437\u0430 \u0434\u0438\u0440\u0435\u043a\u0442\u043d\u043e \u0442\u043e\u0432\u0430 \u0441\u044a\u043e\u0431\u0449\u0435\u043d\u0438\u0435. \u041d\u0435 \u0441\u0435 \u0438\u0437\u043f\u044a\u043b\u043d\u044f\u0432\u0430 \u0435\u0437\u0438\u043a\u043e\u0432 \u043c\u043e\u0434\u0435\u043b."},
gud(){return"SystemOne \u043d\u0435 \u0435 \u043d\u0430\u043b\u0438\u0447\u0435\u043d"},
gu5(){return"\u0410\u0433\u0435\u043d\u0442\u0438\u0442\u0435 \u043c\u043e\u0433\u0430\u0442 \u0434\u0430 \u0438\u0437\u0431\u0438\u0440\u0430\u0442 \u043c\u043e\u0434\u0435\u043b\u0438 \u0437\u0430 \u0432\u0437\u0435\u043c\u0430\u043d\u0435 \u043d\u0430 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0432 \u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u203a \u041c\u043e\u0434\u0435\u043b\u0438. \u041c\u043e\u0434\u0435\u043b, \u0438\u0437\u043a\u043b\u044e\u0447\u0435\u043d \u0442\u0443\u043a, \u043d\u0430\u043f\u0443\u0441\u043a\u0430 \u0442\u043e\u0437\u0438 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u0437\u0430 \u0438\u0437\u0431\u043e\u0440 \u0438 \u0430\u0433\u0435\u043d\u0442\u0438\u0442\u0435, \u043a\u043e\u0438\u0442\u043e \u0441\u0430 \u0433\u043e \u0438\u0437\u0431\u0440\u0430\u043b\u0438, \u0441\u0435 \u0432\u0440\u044a\u0449\u0430\u0442 \u043a\u044a\u043c Auto. \u0414\u043e\u043a\u0430\u0442\u043e \u0432\u0441\u0435\u043a\u0438 \u043c\u043e\u0434\u0435\u043b \u0435 \u0438\u0437\u043a\u043b\u044e\u0447\u0435\u043d, \u043c\u043e\u0434\u0435\u043b\u0438\u0442\u0435 SystemOne, \u043a\u043e\u0438\u0442\u043e \u0434\u043e\u0441\u0442\u0430\u0432\u0447\u0438\u0446\u0438\u0442\u0435 \u0434\u043e\u0431\u0430\u0432\u044f\u0442 \u043f\u043e-\u043a\u044a\u0441\u043d\u043e, \u0441\u044a\u0449\u043e \u0437\u0430\u043f\u043e\u0447\u0432\u0430\u0442 \u0434\u0430 \u0441\u0435 \u0438\u0437\u043a\u043b\u044e\u0447\u0432\u0430\u0442."},
guL(){return"\u0412\u0441\u0435 \u043e\u0449\u0435 \u043d\u044f\u043c\u0430 \u043c\u043e\u0434\u0435\u043b\u0438 SystemOne. \u0414\u043e\u0431\u0430\u0432\u0435\u0442\u0435 \u043a\u043b\u044e\u0447 TypeSafe \u0438\u043b\u0438 OpenRouter \u043f\u043e\u0434 Providers \u0438\u043b\u0438 \u0438\u0437\u0442\u0435\u0433\u043b\u0435\u0442\u0435 \u043c\u043e\u0434\u0435\u043b \u043d\u0430 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043a\u0430\u0442\u043e nimble \u0432 Ollama 0.35 \u0438\u043b\u0438 \u043f\u043e-\u043d\u043e\u0432\u0430 \u0432\u0435\u0440\u0441\u0438\u044f."},
gMC(){return"\u0412\u0441\u0435 \u043e\u0449\u0435 \u043d\u0435 \u0435 \u043d\u0430\u043b\u0438\u0447\u0435\u043d \u043c\u043e\u0434\u0435\u043b SystemOne. \u0414\u043e\u0431\u0430\u0432\u0435\u0442\u0435 \u043a\u043b\u044e\u0447 TypeSafe \u0438\u043b\u0438 OpenRouter \u0432 \u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u203a \u041c\u043e\u0434\u0435\u043b\u0438 \u203a \u0414\u043e\u043d\u0435\u0441\u0435\u0442\u0435 \u0441\u0432\u043e\u0439 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d \u043a\u043b\u044e\u0447 \u0438\u043b\u0438 \u0438\u0437\u0442\u0435\u0433\u043b\u0435\u0442\u0435 \u043c\u043e\u0434\u0435\u043b \u0437\u0430 \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043a\u0430\u0442\u043e nimble \u0432 Ollama."},
gug(){return"systemone \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u0435\u0434\u043d\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 jev typesafe openrouter ollama \u043d\u0430\u043b\u0438\u0447\u043d\u043e\u0441\u0442 \u0430\u043a\u0442\u0438\u0432\u0438\u0440\u0430\u043d\u0435 \u0434\u0435\u0430\u043a\u0442\u0438\u0432\u0438\u0440\u0430\u043d\u0435"},
