gpZ(){return"\u0421\u043f\u043e\u0434\u0435\u043b\u0435\u043d\u043e \u043e\u0442 \u0432\u0441\u0438\u0447\u043a\u0438 \u0432\u0430\u0448\u0438 \u0430\u0433\u0435\u043d\u0442\u0438"},
gp6(){return"\u041e\u0442\u043d\u0430\u0441\u044f \u0441\u0435 \u0437\u0430"},
gpV(){return"\u0417\u0430\u043f\u0430\u0437\u0432\u0430 \u0441\u0435..."},
