gq0(){return"\u0422\u044a\u0440\u0441\u0435\u043d\u0435 \u0432\u044a\u0432 \u0432\u0441\u0438\u0447\u043a\u0438 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438"},
gjq(){return"\u041f\u0440\u043e\u0444\u0438\u043b"},
