gpK(){return"\u0418\u0437\u043f\u043e\u043b\u0437\u0432\u0430\u043d\u0435"},
gpC(){return"\u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f"},
