gpE(){return"\u041f\u043b\u0430\u0442\u0444\u043e\u0440\u043c\u0438"},
gpF(){return"\u0412\u0430\u0448\u0435\u0442\u043e \u0438\u043c\u0435 \u0438 \u0438\u043c\u0435\u0439\u043b, \u043a\u043e\u043f\u0438\u0435 \u043d\u0430 \u0432\u0430\u0448\u0438\u0442\u0435 \u0434\u0430\u043d\u043d\u0438 \u0438 \u0438\u0437\u043b\u0438\u0437\u0430\u043d\u0435."},
gpH(){return"\u041f\u0430\u0440\u043e\u043b\u0430, \u0434\u0432\u0443\u0444\u0430\u043a\u0442\u043e\u0440\u043d\u043e \u0443\u0434\u043e\u0441\u0442\u043e\u0432\u0435\u0440\u044f\u0432\u0430\u043d\u0435, \u043a\u043b\u044e\u0447\u043e\u0432\u0435 \u0437\u0430 \u0441\u0438\u0433\u0443\u0440\u043d\u043e\u0441\u0442 \u0438 \u043a\u044a\u0434\u0435 \u0441\u0442\u0435 \u0432\u043b\u0435\u0437\u043b\u0438."},
gpL(){return"\u0412\u0430\u0448\u0438\u0442\u0435 \u043b\u0438\u043c\u0438\u0442\u0438 \u0438 \u0441\u0438\u043c\u0432\u043e\u043b\u0438\u0447\u043d\u0438 \u0440\u0430\u0437\u0445\u043e\u0434\u0438, \u0432\u0441\u0438\u0447\u043a\u043e \u043d\u0430 \u0435\u0434\u043d\u043e \u043c\u044f\u0441\u0442\u043e."},
gpu(){return"\u0421\u044a\u0437\u0434\u0430\u0439\u0442\u0435 \u0430\u0433\u0435\u043d\u0442\u0438 \u0438 \u0438\u0437\u0431\u0435\u0440\u0435\u0442\u0435 \u043a\u043e\u0439 \u043e\u0442\u0433\u043e\u0432\u0430\u0440\u044f \u043f\u043e \u043f\u043e\u0434\u0440\u0430\u0437\u0431\u0438\u0440\u0430\u043d\u0435."},
gpD(){return"\u041a\u0430\u043a\u0432\u043e \u043c\u043e\u0433\u0430\u0442 \u0434\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u044f\u0442 \u0432\u0430\u0448\u0438\u0442\u0435 \u0430\u0433\u0435\u043d\u0442\u0438, \u0431\u0435\u0437 \u043f\u044a\u0440\u0432\u043e \u0434\u0430 \u0432\u0438 \u043f\u043e\u043f\u0438\u0442\u0430\u0442."},
gpy(){return"\u041a\u043e\u043c\u043f\u044e\u0442\u044a\u0440\u044a\u0442, \u043d\u0430 \u043a\u043e\u0439\u0442\u043e \u0440\u0430\u0431\u043e\u0442\u044f\u0442 \u0432\u0430\u0448\u0438\u0442\u0435 \u0430\u0433\u0435\u043d\u0442\u0438, \u0438 \u0441\u0430\u0439\u0442\u043e\u0432\u0435\u0442\u0435, \u043a\u043e\u0438\u0442\u043e \u043c\u043e\u0433\u0430\u0442 \u0434\u0430 \u0447\u0435\u0442\u0430\u0442 \u043a\u0430\u0442\u043e \u0432\u0430\u0441."},
gpB(){return"\u041a\u043e\u0438 \u043c\u043e\u0434\u0435\u043b\u0438 \u0438\u0437\u043f\u043e\u043b\u0437\u0432\u0430 \u0442\u043e\u0437\u0438 \u0430\u0433\u0435\u043d\u0442 \u0438 API \u043a\u043b\u044e\u0447\u043e\u0432\u0435\u0442\u0435, \u043a\u043e\u0438\u0442\u043e \u043f\u043b\u0430\u0449\u0430\u0442 \u0437\u0430 \u0442\u044f\u0445."},
gpw(){return"\u041a\u0430\u043a \u0433\u043e\u0432\u043e\u0440\u0438 \u0442\u043e\u0437\u0438 \u0430\u0433\u0435\u043d\u0442 \u0438 \u043a\u0430\u043a \u0440\u0430\u0437\u0447\u0438\u0442\u0430 \u0433\u0440\u0443\u043f\u043e\u0432 \u0447\u0430\u0442."},
