gpz(){return"\u0412\u044a\u043d\u0448\u0435\u043d \u0432\u0438\u0434, \u0435\u0437\u0438\u043a, \u0447\u0430\u0441\u043e\u0432\u0430 \u0437\u043e\u043d\u0430 \u0438 \u043a\u0430\u043a\u0432\u043e \u043f\u0440\u0430\u0432\u0438 \u0442\u043e\u0432\u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0432\u044a\u0432 \u0444\u043e\u043d\u043e\u0432 \u0440\u0435\u0436\u0438\u043c."},
gpJ(){return"\u0421\u044a\u0440\u0432\u044a\u0440\u044a\u0442, \u043a\u043e\u0439\u0442\u043e \u0442\u043e\u0437\u0438 \u043f\u0440\u043e\u0437\u043e\u0440\u0435\u0446 \u0438\u0437\u043f\u043e\u043b\u0437\u0432\u0430, \u0442\u043e\u0437\u0438 \u043d\u0430 \u0442\u043e\u0437\u0438 \u043a\u043e\u043c\u043f\u044e\u0442\u044a\u0440 \u0438 \u0430\u043a\u0442\u0443\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u043d\u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f."},
