gpL(){return"\u03a4\u03b1 \u03cc\u03c1\u03b9\u03b1 \u03ba\u03b1\u03b9 \u03bf\u03b9 \u03c3\u03c5\u03bc\u03b2\u03bf\u03bb\u03b9\u03ba\u03ad\u03c2 \u03b4\u03b1\u03c0\u03ac\u03bd\u03b5\u03c2 \u03c3\u03b1\u03c2, \u03cc\u03bb\u03b1 \u03c3\u03b5 \u03ad\u03bd\u03b1 \u03bc\u03ad\u03c1\u03bf\u03c2."},
gpu(){return"\u0394\u03b7\u03bc\u03b9\u03bf\u03c5\u03c1\u03b3\u03ae\u03c3\u03c4\u03b5 \u03c0\u03c1\u03ac\u03ba\u03c4\u03bf\u03c1\u03b5\u03c2 \u03ba\u03b1\u03b9 \u03b5\u03c0\u03b9\u03bb\u03ad\u03be\u03c4\u03b5 \u03c0\u03bf\u03b9\u03bf\u03c2 \u03b8\u03b1 \u03b1\u03c0\u03b1\u03bd\u03c4\u03ae\u03c3\u03b5\u03b9 \u03b1\u03c0\u03cc \u03c0\u03c1\u03bf\u03b5\u03c0\u03b9\u03bb\u03bf\u03b3\u03ae."},
gpD(){return"\u03a4\u03b9 \u03bc\u03c0\u03bf\u03c1\u03bf\u03cd\u03bd \u03bd\u03b1 \u03ba\u03ac\u03bd\u03bf\u03c5\u03bd \u03bf\u03b9 \u03c0\u03c1\u03ac\u03ba\u03c4\u03bf\u03c1\u03ad\u03c2 \u03c3\u03b1\u03c2 \u03c7\u03c9\u03c1\u03af\u03c2 \u03bd\u03b1 \u03c3\u03b1\u03c2 \u03c1\u03c9\u03c4\u03ae\u03c3\u03bf\u03c5\u03bd \u03c0\u03c1\u03ce\u03c4\u03b1."},
gpy(){return"\u039f \u03c5\u03c0\u03bf\u03bb\u03bf\u03b3\u03b9\u03c3\u03c4\u03ae\u03c2 \u03c3\u03c4\u03bf\u03bd \u03bf\u03c0\u03bf\u03af\u03bf \u03b5\u03c1\u03b3\u03ac\u03b6\u03bf\u03bd\u03c4\u03b1\u03b9 \u03bf\u03b9 \u03c0\u03c1\u03ac\u03ba\u03c4\u03bf\u03c1\u03b5\u03c2 \u03c3\u03b1\u03c2 \u03ba\u03b1\u03b9 \u03bf\u03b9 \u03b9\u03c3\u03c4\u03cc\u03c4\u03bf\u03c0\u03bf\u03b9 \u03c0\u03bf\u03c5 \u03bc\u03c0\u03bf\u03c1\u03bf\u03cd\u03bd \u03bd\u03b1 \u03b4\u03b9\u03b1\u03b2\u03ac\u03c3\u03bf\u03c5\u03bd \u03c9\u03c2 \u03b5\u03c3\u03ac\u03c2."},
gpB(){return"\u03a0\u03bf\u03b9\u03b1 \u03bc\u03bf\u03bd\u03c4\u03ad\u03bb\u03b1 \u03c7\u03c1\u03b7\u03c3\u03b9\u03bc\u03bf\u03c0\u03bf\u03b9\u03b5\u03af \u03b1\u03c5\u03c4\u03cc\u03c2 \u03bf \u03c0\u03c1\u03ac\u03ba\u03c4\u03bf\u03c1\u03b1\u03c2 \u03ba\u03b1\u03b9 \u03c4\u03b1 \u03ba\u03bb\u03b5\u03b9\u03b4\u03b9\u03ac API \u03c0\u03bf\u03c5 \u03c0\u03bb\u03b7\u03c1\u03ce\u03bd\u03bf\u03c5\u03bd \u03b3\u03b9\u03b1 \u03b1\u03c5\u03c4\u03ac."},
gpw(){return"\u03a0\u03ce\u03c2 \u03bc\u03b9\u03bb\u03ac\u03b5\u03b9 \u03b1\u03c5\u03c4\u03cc\u03c2 \u03bf \u03c0\u03c1\u03ac\u03ba\u03c4\u03bf\u03c1\u03b1\u03c2 \u03ba\u03b1\u03b9 \u03c0\u03ce\u03c2 \u03b4\u03b9\u03b1\u03b2\u03ac\u03b6\u03b5\u03b9 \u03bc\u03b9\u03b1 \u03bf\u03bc\u03b1\u03b4\u03b9\u03ba\u03ae \u03c3\u03c5\u03bd\u03bf\u03bc\u03b9\u03bb\u03af\u03b1."},
