gDb(){return"\u0391\u03c1\u03c7\u03b5\u03af\u03b1, \u03b1\u03bd\u03b1\u03bc\u03bd\u03ae\u03c3\u03b5\u03b9\u03c2 \u03ba\u03b1\u03b9 \u03cc,\u03c4\u03b9 \u03ac\u03bb\u03bb\u03bf \u03b1\u03c0\u03bf\u03b8\u03b7\u03ba\u03b5\u03cd\u03b5\u03c4\u03b5"},
gDc(){return"\u03a4\u03bf \u03cc\u03bd\u03bf\u03bc\u03b1, \u03c4\u03bf email, \u03b7 \u03b4\u03b9\u03b5\u03cd\u03b8\u03c5\u03bd\u03c3\u03b7 IP \u03ba\u03b1\u03b9 \u03b7 \u03c4\u03bf\u03c0\u03bf\u03b8\u03b5\u03c3\u03af\u03b1 \u03c3\u03b1\u03c2"},
gD9(){return"\u039f\u03b9 \u03bb\u03bf\u03b3\u03b1\u03c1\u03b9\u03b1\u03c3\u03bc\u03bf\u03af \u03bc\u03b5 \u03c4\u03bf\u03c5\u03c2 \u03bf\u03c0\u03bf\u03af\u03bf\u03c5\u03c2 \u03c3\u03c5\u03bd\u03b4\u03ad\u03b5\u03c4\u03b5 \u03b5\u03bd\u03c3\u03c9\u03bc\u03b1\u03c4\u03ce\u03c3\u03b5\u03b9\u03c2"},
gDk(){return"\u039f\u03b9 \u03b4\u03b9\u03b1\u03c7\u03b5\u03b9\u03c1\u03b9\u03c3\u03c4\u03ad\u03c2 \u03b2\u03bb\u03ad\u03c0\u03bf\u03c5\u03bd \u03bc\u03cc\u03bd\u03bf \u03c3\u03cd\u03bd\u03bf\u03bb\u03b1 \u03b3\u03b9\u03b1 \u03cc\u03bb\u03bf\u03c5\u03c2 \u03cc\u03c3\u03bf\u03c5\u03c2 \u03ba\u03bf\u03b9\u03bd\u03bf\u03c0\u03bf\u03b9\u03bf\u03cd\u03bd, \u03c0\u03bf\u03c4\u03ad \u03b5\u03c3\u03ac\u03c2 \u03bc\u03b5\u03bc\u03bf\u03bd\u03c9\u03bc\u03ad\u03bd\u03b1. \u0391\u03c0\u03b5\u03bd\u03b5\u03c1\u03b3\u03bf\u03c0\u03bf\u03b9\u03ae\u03c3\u03c4\u03b5 \u03c4\u03bf \u03bf\u03c0\u03bf\u03c4\u03b5\u03b4\u03ae\u03c0\u03bf\u03c4\u03b5 \u03ba\u03b1\u03b9 \u03b2\u03b3\u03b1\u03af\u03bd\u03b5\u03c4\u03b5 \u03b1\u03bc\u03ad\u03c3\u03c9\u03c2 \u03b1\u03c0\u03cc \u03c4\u03b1 \u03c3\u03cd\u03bd\u03bf\u03bb\u03b1."},
gD7(){return"\u039a\u03bf\u03b9\u03bd\u03bf\u03c0\u03bf\u03af\u03b7\u03c3\u03b7 \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03c9\u03bd \u03c7\u03c1\u03ae\u03c3\u03b7\u03c2;"},
gD6(){return"\u039a\u03bf\u03b9\u03bd\u03bf\u03c0\u03bf\u03af\u03b7\u03c3\u03b7"},
gi_(){return"\u039a\u03bf\u03b9\u03bd\u03cc\u03c7\u03c1\u03b7\u03c3\u03c4\u03b7 \u03c7\u03c1\u03ae\u03c3\u03b7"},
qL(a,b){return"\u039b\u03bf\u03b3\u03b1\u03c1\u03b9\u03b1\u03c3\u03bc\u03bf\u03af \u03c0\u03bf\u03c5 \u03ba\u03bf\u03b9\u03bd\u03bf\u03c0\u03bf\u03b9\u03bf\u03cd\u03bd \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03b1 \u03c7\u03c1\u03ae\u03c3\u03b7\u03c2: "+a+" \u03b1\u03c0\u03cc "+b+". \u039c\u03cc\u03bd\u03bf \u03c3\u03cd\u03bd\u03bf\u03bb\u03b1, \u03c7\u03c9\u03c1\u03af\u03c2 \u03c0\u03b5\u03c1\u03b9\u03b5\u03c7\u03cc\u03bc\u03b5\u03bd\u03bf."},
gqv(){return"\u039a\u03b1\u03bd\u03b5\u03af\u03c2 \u03b4\u03b5\u03bd \u03ba\u03bf\u03b9\u03bd\u03bf\u03c0\u03bf\u03b9\u03b5\u03af \u03b1\u03ba\u03cc\u03bc\u03b7 \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03b1 \u03c7\u03c1\u03ae\u03c3\u03b7\u03c2. \u0395\u03bd\u03b5\u03c1\u03b3\u03bf\u03c0\u03bf\u03b9\u03b5\u03af\u03c4\u03b1\u03b9 \u03b1\u03c0\u03cc \u03a1\u03c5\u03b8\u03bc\u03af\u03c3\u03b5\u03b9\u03c2, \u03a0\u03c1\u03bf\u03c6\u03af\u03bb, \u03a4\u03b1 \u03b4\u03b5\u03b4\u03bf\u03bc\u03ad\u03bd\u03b1 \u03c3\u03b1\u03c2."},
gqN(){return"\u039a\u03bf\u03b9\u03bd\u03bf\u03c0\u03bf\u03b9\u03b7\u03bc\u03ad\u03bd\u03b5\u03c2 \u03b5\u03ba\u03c4\u03b5\u03bb\u03ad\u03c3\u03b5\u03b9\u03c2"},
gqt(){return"\u039c\u03ad\u03c3\u03b7 \u03b4\u03b9\u03ac\u03c1\u03ba\u03b5\u03b9\u03b1"},
gju(){return"\u039f\u03bb\u03bf\u03ba\u03bb\u03b7\u03c1\u03c9\u03bc\u03ad\u03bd\u03b5\u03c2 \u03b5\u03ba\u03c4\u03b5\u03bb\u03ad\u03c3\u03b5\u03b9\u03c2"},
gqP(){return"\u0392\u03ae\u03bc\u03b1\u03c4\u03b1 \u03b1\u03bd\u03ac \u03b5\u03ba\u03c4\u03ad\u03bb\u03b5\u03c3\u03b7"},
gqu(){return"\u03a3\u03c5\u03c3\u03ba\u03b5\u03c5\u03ad\u03c2"},
gqs(){return"\u0395\u03ba\u03b4\u03cc\u03c3\u03b5\u03b9\u03c2 \u03b5\u03c6\u03b1\u03c1\u03bc\u03bf\u03b3\u03ae\u03c2"},
gqG(){return"\u0393\u03bb\u03ce\u03c3\u03c3\u03b5\u03c2"},
