gKP(){return"\u0396\u03c9\u03bd\u03c4\u03b1\u03bd\u03ae \u03c6\u03c9\u03bd\u03ae"},
gKN(){return"\u0391\u03bd\u03b1\u03b6\u03ae\u03c4\u03b7\u03c3\u03b7 \u03c3\u03c4\u03b7 \u03bc\u03bd\u03ae\u03bc\u03b7"},
gKO(){return"\u0394\u03b7\u03bc\u03b9\u03bf\u03c5\u03c1\u03b3\u03af\u03b1 \u03b5\u03b9\u03ba\u03cc\u03bd\u03c9\u03bd"},
gKQ(){return"\u0391\u03bd\u03b1\u03b6\u03ae\u03c4\u03b7\u03c3\u03b7 \u03c3\u03c4\u03bf web"},
KG(a){return"\u0394\u03b9\u03b1\u03b8\u03ad\u03c3\u03b9\u03bc\u03b1 \u03c3\u03c4\u03bf NeoRouter \u03c3\u03b1\u03c2: "+a},
gKI(){return"\u0394\u03b5\u03bd \u03c5\u03c0\u03ac\u03c1\u03c7\u03b5\u03b9 \u03b1\u03ba\u03cc\u03bc\u03b7 \u03c4\u03af\u03c0\u03bf\u03c4\u03b1 \u03c3\u03c4\u03bf NeoRouter \u03c3\u03b1\u03c2."},
gKL(){return"\u03a4\u03bf NeoRouter \u03b5\u03c0\u03b9\u03bb\u03ad\u03b3\u03b5\u03b9 \u03c4\u03bf \u03bc\u03bf\u03bd\u03c4\u03ad\u03bb\u03bf \u03b3\u03b9\u03b1 \u03ba\u03ac\u03b8\u03b5 \u03b1\u03af\u03c4\u03b7\u03bc\u03b1, \u03bf\u03c0\u03cc\u03c4\u03b5 \u03b1\u03c5\u03c4\u03ae \u03b7 \u03b5\u03c0\u03b9\u03bb\u03bf\u03b3\u03ae \u03b4\u03b5\u03bd \u03c7\u03c1\u03b7\u03c3\u03b9\u03bc\u03bf\u03c0\u03bf\u03b9\u03b5\u03af\u03c4\u03b1\u03b9."},
KJ(a){return"\u03a3\u03c4\u03bf NeoRouter \u03c3\u03b1\u03c2: "+a+", \u03b1\u03bb\u03bb\u03ac \u03c4\u03bf \u03ba\u03bb\u03b5\u03b9\u03b4\u03af \u03c4\u03bf\u03c5 NeoAgent \u03b4\u03b5\u03bd \u03bc\u03c0\u03bf\u03c1\u03b5\u03af \u03b1\u03ba\u03cc\u03bc\u03b7 \u03bd\u03b1 \u03c4\u03b1 \u03c7\u03c1\u03b7\u03c3\u03b9\u03bc\u03bf\u03c0\u03bf\u03b9\u03ae\u03c3\u03b5\u03b9 (\u03c0.\u03c7. \u03c4\u03b1 \u03b5\u03c0\u03af \u03c0\u03bb\u03b7\u03c1\u03c9\u03bc\u03ae). \u0395\u03c0\u03b9\u03c4\u03c1\u03ad\u03c8\u03c4\u03b5 \u03c4\u03b1 \u03b3\u03b9\u03b1 \u03c4\u03bf NeoAgent \u03c3\u03c4\u03b1 \u039a\u03bb\u03b5\u03b9\u03b4\u03b9\u03ac API \u03c4\u03bf\u03c5 NeoRouter."},
